class Solution {
    private static final int MOD = 1_000_000_007;

    private long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }

    public int colorWays(int n) {
        if (n == 1) return 3;
        if (n == 2) return 6;
        long p2 = modPow(2, n);
        if (n % 2 == 0) return (int)((p2 + 2) % MOD);
        return (int)((p2 - 2 + MOD) % MOD);
    }
}

